// Generated by MCSuperMods: msm:throwable as the runtime's MsmThrowableItem.
package msm_test.item;

import msm_test.entity.ThrownItemEntity;
import java.util.Optional;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.Position;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.sounds.SoundEvent;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.stats.Stats;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.entity.projectile.Projectile;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.ItemUseAnimation;
import net.minecraft.world.item.ProjectileItem;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.Vec3;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * An item that is thrown as a {@link ThrownItemEntity}, at once ({@code charge_ticks} 0, as a snowball) or on release
 * after holding use for {@code charge_ticks} (as a trident). {@code msm:on_use} fires first ({@link #onUse}). What the
 * stack loses depends on {@code after_throw}: {@code CONSUME}, {@code DROP} and {@code RETURN} take one item (none in
 * creative, as vanilla's {@code consume}); {@code KEEP} takes none. A damageable item: {@code KEEP} damages the held
 * stack by one, {@code DROP} and {@code RETURN} damage the thrown copy by one. A dispenser throws it through
 * {@link ProjectileItem} when the item is registered with {@code DispenserBlock.registerProjectileBehavior}.
 */
public class ThrowableItem extends Item implements ProjectileItem {
    /** The use duration while charging, as vanilla's trident and bow. */
    static final int USE_DURATION = 72000;
    /** The default speed, the snowball's. */
    static final float DEFAULT_SPEED = 1.5f;
    /** Vanilla's dispenser power for snowballs relative to the thrown speed 1.5. */
    static final float DISPENSE_POWER_FACTOR = 1.1f / DEFAULT_SPEED;

    private static final Logger LOGGER = LoggerFactory.getLogger("msm_test");

    /** What happens to the item after a throw ({@code after_throw}). */
    public enum AfterThrow {
        /** One item is used up (a snowball). */
        CONSUME,
        /** The held stack stays (a wand). */
        KEEP,
        /** The thrown item drops where it lands (a throwing knife). */
        DROP,
        /** The thrown item goes back into the thrower's inventory when it lands, or drops at their feet. */
        RETURN
    }

    /**
     * The settings of {@code msm:throwable}.
     *
     * @param sound the throw sound id, or null for the snowball's
     */
    public record Settings(float speed, float inaccuracy, float gravity, float damage, int chargeTicks, AfterThrow afterThrow,
            int cooldownTicks, String sound) {}

    private final Settings settings;
    private final SoundEvent sound;

    public ThrowableItem(Item.Properties properties, String owner, Settings settings) {
        super(properties);
        this.settings = settings;
        this.sound = throwSound(owner, settings.sound());
    }

    /** The throw sound: {@code sound}, else the snowball's; an unknown sound is logged and the snowball's is used. */
    private static SoundEvent throwSound(String owner, String id) {
        if (id != null) {
            Optional<SoundEvent> sound = BuiltInRegistries.SOUND_EVENT.getOptional(Identifier.parse(id));
            if (sound.isPresent()) {
                return sound.get();
            }
            LOGGER.warn("{}: msm:throwable: unknown sound {}; the snowball sound is used", owner, id);
        }
        return SoundEvents.SNOWBALL_THROW;
    }

    public Settings settings() {
        return settings;
    }

    /** Fails on cooldown; otherwise {@code msm:on_use} fires and the item is thrown or starts charging. */
    @Override
    public InteractionResult use(Level level, Player player, InteractionHand hand) {
        ItemStack stack = player.getItemInHand(hand);
        if (player.getCooldowns().isOnCooldown(stack)) {
            return InteractionResult.FAIL;
        }
        onUse(level, player, hand, stack);
        if (settings.chargeTicks() > 0) {
            player.startUsingItem(hand);
            return InteractionResult.CONSUME;
        }
        throwFrom(level, player, hand, stack);
        return InteractionResult.SUCCESS;
    }

    /** {@code msm:on_use}, before the throw or the charge; nothing by default. */
    protected void onUse(Level level, Player player, InteractionHand hand, ItemStack stack) {}

    /** {@code on_hit_entity}, after the damage; nothing by default. */
    public void onHitEntity(ServerLevel level, Vec3 at, BlockPos base, Entity thrower, LivingEntity hit) {}

    /** {@code on_hit_block}; nothing by default. */
    public void onHitBlock(ServerLevel level, Vec3 at, BlockPos pos, Entity thrower) {}

    @Override
    public int getUseDuration(ItemStack stack, LivingEntity entity) {
        return settings.chargeTicks() > 0 ? USE_DURATION : 0;
    }

    /** {@code SPEAR} while charging (the arm raised behind the head); none for a throw on use. */
    @Override
    public ItemUseAnimation getUseAnimation(ItemStack stack) {
        return settings.chargeTicks() > 0 ? ItemUseAnimation.SPEAR : ItemUseAnimation.NONE;
    }

    /** Throws when use was held for at least {@code charge_ticks}; an earlier release does nothing. */
    @Override
    public boolean releaseUsing(ItemStack stack, Level level, LivingEntity entity, int timeLeft) {
        if (settings.chargeTicks() <= 0 || !(entity instanceof Player player)) {
            return false;
        }
        int held = getUseDuration(stack, entity) - timeLeft;
        if (held < settings.chargeTicks()) {
            return false;
        }
        InteractionHand hand = player.getUsedItemHand();
        throwFrom(level, player, hand, stack);
        return true;
    }

    /** Spawns the projectile (server), plays the sound, applies {@code after_throw} and the cooldown. */
    void throwFrom(Level level, Player player, InteractionHand hand, ItemStack stack) {
        ItemStack thrown = stack.copyWithCount(1);
        ItemStack cooldownKey = stack.copyWithCount(1);
        boolean infinite = player.hasInfiniteMaterials();
        AfterThrow mode = settings.afterThrow();
        boolean carriesItem = (mode == AfterThrow.DROP || mode == AfterThrow.RETURN) && !infinite;
        if (carriesItem && thrown.isDamageableItem()) {
            thrown.setDamageValue(thrown.getDamageValue() + 1);
        }
        level.playSound(null, player.getX(), player.getY(), player.getZ(), sound, SoundSource.NEUTRAL, 0.5f,
                0.4f / (level.getRandom().nextFloat() * 0.4f + 0.8f));
        if (level instanceof ServerLevel server) {
            boolean broken = thrown.isDamageableItem() && thrown.getDamageValue() >= thrown.getMaxDamage();
            Projectile.spawnProjectileFromRotation((l, thrower, s) -> {
                ThrownItemEntity entity = new ThrownItemEntity(l, thrower, s);
                entity.setCarriesItem(carriesItem && !broken);
                return entity;
            }, server, thrown, player, 0.0f, settings.speed(), settings.inaccuracy());
        }
        player.awardStat(Stats.ITEM_USED.get(this));
        switch (mode) {
            case CONSUME, DROP, RETURN -> stack.consume(1, player);
            case KEEP -> {
                if (stack.isDamageableItem()) {
                    stack.hurtAndBreak(1, player, hand);
                }
            }
        }
        if (settings.cooldownTicks() > 0) {
            player.getCooldowns().addCooldown(cooldownKey, settings.cooldownTicks());
        }
    }

    /** The dispenser's projectile: a copy of one item, which does not come back ({@code after_throw} needs a thrower). */
    @Override
    public Projectile asProjectile(Level level, Position position, ItemStack stack, Direction direction) {
        ThrownItemEntity entity = new ThrownItemEntity(level, position.x(), position.y(), position.z(), stack.copyWithCount(1));
        entity.setCarriesItem(settings.afterThrow() == AfterThrow.DROP || settings.afterThrow() == AfterThrow.RETURN);
        return entity;
    }

    /** Vanilla's snowball dispense settings, with the power scaled by {@code speed}. */
    @Override
    public DispenseConfig createDispenseConfig() {
        return DispenseConfig.builder().power(settings.speed() * DISPENSE_POWER_FACTOR).build();
    }
}
